import{_ as l,C as s,o as c,c as h,a6 as d,E as a,w as r,j as e,a as t}from"./chunks/framework.DIp0zHSV.js";const S=JSON.parse('{"title":"Sound Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/sounds.md","filePath":"configuration/sounds.md","lastUpdated":1791669045000}'),u={name:"configuration/sounds.md"};function p(g,o,b,v,m,f){const n=s("PluginTabsTab"),i=s("PluginTabs");return c(),h("div",null,[o[2]||(o[2]=d('<h1 id="sound-configuration" tabindex="-1">Sound Configuration <a class="header-anchor" href="#sound-configuration" aria-label="Permalink to &quot;Sound Configuration&quot;">​</a></h1><blockquote><p><strong>LCARS-style audio feedback for card interactions and HA UI events</strong></p></blockquote><p>LCARdS can play sounds for card taps, navigation, dialogs, alert mode changes, and more. Sounds are <strong>off by default</strong>: you need to create the helper entities and enable the master toggle before any sound plays. Once enabled, all categories are on and the built-in scheme plays immediately with no further configuration.</p><hr><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><p>Open <strong>Config Panel</strong> → <strong>Helpers</strong> tab and create the helpers.</p><p>The HA input helpers that store and control certain global sound settings. You only need to do this once.</p><hr><h2 id="enabling-sounds" tabindex="-1">Enabling Sounds <a class="header-anchor" href="#enabling-sounds" aria-label="Permalink to &quot;Enabling Sounds&quot;">​</a></h2><p>Sounds won&#39;t play until <code>input_boolean.lcards_sound_enabled</code> is turned on. Toggle it from:</p><ul><li>The <strong>Sound</strong> tab in the Config Panel</li><li>Your HA dashboard directly</li><li>An automation</li></ul><p>The three category toggles (<code>lcards_sound_cards</code>, <code>lcards_sound_ui</code>, <code>lcards_sound_alerts</code>) let you enable/disable each group independently. All three default to enabled once the master is on.</p><hr><h2 id="sound-schemes" tabindex="-1">Sound Schemes <a class="header-anchor" href="#sound-schemes" aria-label="Permalink to &quot;Sound Schemes&quot;">​</a></h2><p>A scheme maps every event to an audio file. Select your scheme from the <strong>Sound Scheme</strong> dropdown in the Sound tab (or via the <code>input_select.lcards_sound_scheme</code> entity).</p><p><strong>Built-in scheme: <code>lcards_default</code></strong></p><p>Covers all event types with LCARS-style beeps and tones. Additional schemes become available when sound packs are installed.</p><p>Set to <strong>none</strong> to use the default built-in scheme. To disable all sounds, turn off the master <strong>Sound Effects Enabled</strong> toggle.</p><hr><h2 id="per-event-overrides" tabindex="-1">Per-Event Overrides <a class="header-anchor" href="#per-event-overrides" aria-label="Permalink to &quot;Per-Event Overrides&quot;">​</a></h2><p>You can assign a different sound (or silence) to any individual event, independent of the active scheme.</p><p>In the Sound tab, find the event in the overrides table and pick an asset from the dropdown, or set it to <strong>(Use scheme default)</strong> to revert. When any overrides are active, a <strong>Reset all to scheme defaults</strong> button appears above the table to clear them all at once.</p><p>Overrides set in the <strong>Global Settings</strong> section are shared across all users and all devices (they apply to everyone who hasn&#39;t set a more specific override).</p><p>To set overrides that only apply to you or a specific device, use the <strong>Per-User / Per-Device Overrides</strong> section below.</p><hr><h2 id="per-user-per-device-overrides" tabindex="-1">Per-User / Per-Device Overrides <a class="header-anchor" href="#per-user-per-device-overrides" aria-label="Permalink to &quot;Per-User / Per-Device Overrides&quot;">​</a></h2><blockquote><p><strong>Requires</strong>: LCARdS integration v1.12+ with <code>scoped_storage</code> capability.</p></blockquote><p>The <strong>Per-User / Per-Device Overrides</strong> section at the bottom of the Sound tab lets you set sound settings that only apply to a specific user or device, without changing the global defaults.</p><h3 id="scope-selector" tabindex="-1">Scope selector <a class="header-anchor" href="#scope-selector" aria-label="Permalink to &quot;Scope selector&quot;">​</a></h3><p>Use the <strong>User</strong> / <strong>Device</strong> buttons to switch between the two scopes:</p><ul><li><strong>User</strong>: settings apply to your HA user account on any device</li><li><strong>Device</strong>: settings apply to this specific browser/device only</li></ul><h3 id="what-can-be-overridden-per-user-per-device" tabindex="-1">What can be overridden per-user / per-device <a class="header-anchor" href="#what-can-be-overridden-per-user-per-device" aria-label="Permalink to &quot;What can be overridden per-user / per-device&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>User scope</th><th>Device scope</th></tr></thead><tbody><tr><td>Master enable</td><td>✅</td><td>✅</td></tr><tr><td>Volume</td><td>✅</td><td>✅</td></tr><tr><td>Sound scheme</td><td>✅</td><td>✅</td></tr><tr><td>Per-event overrides</td><td>✅</td><td>✅</td></tr></tbody></table><h3 id="resolution-order" tabindex="-1">Resolution order <a class="header-anchor" href="#resolution-order" aria-label="Permalink to &quot;Resolution order&quot;">​</a></h3><p>Every sound setting (volume, scheme, and per-event overrides) follows the same priority chain. The first non-null value found wins:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Card config → Device override → User override → Global setting → Scheme default</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Priority</th><th>What it is</th></tr></thead><tbody><tr><td><strong>Card config</strong></td><td><code>tap_action.sound</code> in a card&#39;s YAML; highest, overrides everything</td></tr><tr><td><strong>Device override</strong></td><td>Set in the Device scope for this browser/device</td></tr><tr><td><strong>User override</strong></td><td>Set in the User scope for your HA account</td></tr><tr><td><strong>Global setting</strong></td><td>The shared default (helpers + global per-event overrides)</td></tr><tr><td><strong>Scheme default</strong></td><td>The active sound scheme&#39;s mapping for that event</td></tr></tbody></table><p>Clearing an override at any level (the × button, or setting a per-event override back to <strong>Use scheme default</strong>) drops that level out of the chain; the next level down takes over automatically.</p><h3 id="admin-editing-other-users-devices" tabindex="-1">Admin: editing other users / devices <a class="header-anchor" href="#admin-editing-other-users-devices" aria-label="Permalink to &quot;Admin: editing other users / devices&quot;">​</a></h3><p>HA admin users see an <strong>Edit as admin</strong> dropdown in each scope section. Selecting a user or device lets the admin view and modify that subject&#39;s overrides directly. Changes take effect on the target&#39;s next playback.</p><hr><h2 id="what-events-are-covered" tabindex="-1">What Events Are Covered <a class="header-anchor" href="#what-events-are-covered" aria-label="Permalink to &quot;What Events Are Covered&quot;">​</a></h2><h3 id="card-interactions" tabindex="-1">Card Interactions <a class="header-anchor" href="#card-interactions" aria-label="Permalink to &quot;Card Interactions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Event</th><th>When</th></tr></thead><tbody><tr><td>Card Tap</td><td>Tapping any LCARdS card or standard HA card</td></tr><tr><td>Card Hold</td><td>Hold action</td></tr><tr><td>Card Double-Tap</td><td>Double-tap action</td></tr><tr><td>Card Hover</td><td>Mouse hover (desktop only)</td></tr><tr><td>Toggle → On / Off</td><td>Toggle state changes</td></tr><tr><td>Slider Grab / Release</td><td>Grabbing or releasing a slider</td></tr><tr><td>More Info Open</td><td>Opening the more-info panel</td></tr></tbody></table><h3 id="ha-ui-navigation" tabindex="-1">HA UI Navigation <a class="header-anchor" href="#ha-ui-navigation" aria-label="Permalink to &quot;HA UI Navigation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Event</th><th>When</th></tr></thead><tbody><tr><td>Menu Expand / Collapse</td><td>Hamburger menu button</td></tr><tr><td>Page / View Navigation</td><td>Moving between dashboard views and sidebar nav items</td></tr><tr><td>Dialog Open</td><td>Any HA dialog opens</td></tr><tr><td>Dialog Close</td><td>Any HA dialog dismissed</td></tr><tr><td>Dashboard Edit Start</td><td>Entering dashboard edit mode</td></tr><tr><td>Dashboard Edit Save / Done</td><td>Exiting dashboard edit mode</td></tr></tbody></table><h3 id="alerts-system" tabindex="-1">Alerts &amp; System <a class="header-anchor" href="#alerts-system" aria-label="Permalink to &quot;Alerts &amp; System&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Event</th><th>When</th></tr></thead><tbody><tr><td>Red Alert</td><td>Alert mode set to <code>red_alert</code></td></tr><tr><td>Yellow Alert</td><td>Alert mode set to <code>yellow_alert</code></td></tr><tr><td>Blue Alert</td><td>Alert mode set to <code>blue_alert</code></td></tr><tr><td>Gray Alert</td><td>Alert mode set to <code>gray_alert</code></td></tr><tr><td>Black Alert</td><td>Alert mode set to <code>black_alert</code></td></tr><tr><td>Alert Clear</td><td>Alert mode cleared (back to normal)</td></tr><tr><td>System Ready</td><td>LCARdS initialization complete</td></tr><tr><td>System Error</td><td>System error condition</td></tr><tr><td>Notification</td><td>General notification</td></tr></tbody></table><hr><h2 id="triggering-from-automations" tabindex="-1">Triggering from Automations <a class="header-anchor" href="#triggering-from-automations" aria-label="Permalink to &quot;Triggering from Automations&quot;">​</a></h2><p>Use <a href="/dev/configuration/ha-actions.html#lcards-play-sound"><code>lcards.play_sound</code></a> to play a sound on demand from an automation (e.g. a subtle chime alongside a kiosk tablet wake routine) without changing alert mode or any screen effect. It respects the master <strong>Sound Effects Enabled</strong> toggle but not the category toggles, and supports the same per-device/per-user <a href="/dev/configuration/ha-actions.html#targeting">targeting</a> as every other LCARdS action.</p><hr><h2 id="silencing-a-specific-event" tabindex="-1">Silencing a Specific Event <a class="header-anchor" href="#silencing-a-specific-event" aria-label="Permalink to &quot;Silencing a Specific Event&quot;">​</a></h2><p>In the overrides table, set the event&#39;s asset to <strong>Silence</strong> (the explicit silence option, distinct from &quot;use scheme default&quot;). The active scheme may also silence events: <code>slider_change</code> is silenced in <code>lcards_default</code> to avoid sound on every value tick.</p><hr><h2 id="browser-audio-policy" tabindex="-1">Browser Audio Policy <a class="header-anchor" href="#browser-audio-policy" aria-label="Permalink to &quot;Browser Audio Policy {#browser-audio-policy}&quot;">​</a></h2><p>Browsers block audio playback until the user has interacted with the page (clicked, tapped, or pressed a key). For most LCARdS sounds this is transparent: the first tap on a card or navigation link is the interaction, and sounds play normally from that point on.</p><p>The <strong>System Ready</strong> startup sound is different: it plays immediately after LCARdS finishes initializing, before any user interaction. Browsers will block it by default unless your HA dashboard URL is explicitly allowed to autoplay audio.</p>',58)),a(i,null,{default:r(()=>[a(n,{label:"Chrome / Edge"},{default:r(()=>[...o[0]||(o[0]=[e("ol",null,[e("li",null,[t("Open "),e("strong",null,"Chrome Settings"),t(" → "),e("strong",null,"Privacy and security"),t(" → "),e("strong",null,"Site settings"),t(" → "),e("strong",null,"Additional content settings"),t(" → "),e("strong",null,"Sound")]),e("li",null,[t("Under "),e("strong",null,"Allowed to play sound"),t(", click "),e("strong",null,"Add"),t(" and enter your HA URL (e.g. "),e("code",null,"http://homeassistant.local:8123"),t(" or "),e("code",null,"https://my.ha.instance"),t(")")]),e("li",null,"Hard-refresh your HA dashboard: the startup sound will now play on page load")],-1),e("p",null,[t("Alternatively, click the "),e("strong",null,"🔒 / ℹ️"),t(" icon in the address bar while on your HA page → "),e("strong",null,"Site settings"),t(" → change "),e("strong",null,"Sound"),t(" to "),e("strong",null,"Allow"),t(".")],-1)])]),_:1}),a(n,{label:"Firefox"},{default:r(()=>[...o[1]||(o[1]=[e("ol",null,[e("li",null,[t("Open "),e("strong",null,"Firefox Settings"),t(" → "),e("strong",null,"Privacy & Security"),t(" → scroll to "),e("strong",null,"Permissions"),t(" → "),e("strong",null,"Block websites from automatically playing sound"),t(" → click "),e("strong",null,"Exceptions...")]),e("li",null,[t("Enter your HA URL and click "),e("strong",null,"Allow"),t(" → "),e("strong",null,"Save Changes")]),e("li",null,"Hard-refresh your HA dashboard")],-1),e("p",null,[t("Alternatively, when Firefox shows the autoplay blocked icon (🔇) in the address bar, click it and select "),e("strong",null,"Allow Audio and Video"),t(".")],-1)])]),_:1})]),_:1}),o[3]||(o[3]=d('<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you don&#39;t use the System Ready sound, no browser changes are needed; all other sounds fire after a user interaction and play without restriction.</p></div><hr><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Sounds are off by default. Nothing plays until <code>input_boolean.lcards_sound_enabled</code> exists and is set to <code>on</code>.</li><li>Category toggles (<code>lcards_sound_cards</code>, <code>lcards_sound_ui</code>, <code>lcards_sound_alerts</code>) default to enabled once the master is on; you only need to create them if you want to disable a specific category.</li><li>Volume is shared across all events: there&#39;s no per-event volume.</li><li>Global overrides apply to all users and devices. User-scoped and device-scoped overrides apply only to that user or device respectively; device-scope wins over user-scope on a per-event basis.</li><li>The sound scheme helper&#39;s option list updates automatically as you install sound packs, no manual YAML edits needed.</li><li>Setting the scheme to <strong>none</strong> uses the default built-in scheme. To disable all sounds, use the master <strong>Sound Effects Enabled</strong> toggle.</li></ul><hr>',5))])}const A=l(u,[["render",p]]);export{S as __pageData,A as default};
